#!/bin/bash
set -e

# Prescription drug picker: replaced the separate dropdown + free-text
# input with a single type-ahead search field. Typing filters matching
# medicines (brand or generic, live) as a suggestion list; clicking one
# selects it and its type (for dosage options). If nothing matches,
# there's a 'Browse full list' fallback to the original dropdown, or
# just keep typing to prescribe as free text (unchanged behavior).
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/consultation/[id]"
echo "" | base64 -d > "app/consultation/[id]/consultation-form.js"
echo "Wrote app/consultation/[id]/consultation-form.js"

git add "app/consultation/[id]/consultation-form.js"
git commit -m "Add type-ahead search to Prescription drug picker, with browse-all fallback"
git push

echo "Done."
